begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,aud,role,email) values('00000000-0000-4000-8000-000000000531','authenticated','authenticated','mail053@example.invalid');
\ir fixtures/privacy.inc
insert into public.gmail_accounts(id,user_id,email,status,encrypted_refresh_token,scope_set) values('10000000-0000-4000-8000-000000000531','00000000-0000-4000-8000-000000000531','mail053@example.invalid','CONNECTED','\x74657374',array['https://www.googleapis.com/auth/gmail.readonly','https://www.googleapis.com/auth/gmail.compose']);
create temporary table config as select public.get_automation_configuration('00000000-0000-4000-8000-000000000531') value;
select is((select value->'settings'->>'processingScope' from config),'ALL_INCOMING','La selección inicial conserva el comportamiento existente');
select is((select value->'settings'->'execution'->>'automationEnabled' from config),'false','No se activa automatización al migrar');
select is(public.get_automation_configuration('ffffffff-ffff-4fff-8fff-ffffffffffff'),null::jsonb,'Una identidad inexistente no devuelve configuración');
select lives_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select jsonb_set(jsonb_set(value->'settings','{processingScope}','"UNREAD_INBOX"'),'{excludedDomains}','["example.com"]') from config))$q$,'Se guarda el conjunto de ajustes');
select is((select processing_scope from public.user_settings where user_id='00000000-0000-4000-8000-000000000531'),'UNREAD_INBOX','El worker puede leer la selección guardada');
select is((select classifier_excluded_domains from public.user_settings where user_id='00000000-0000-4000-8000-000000000531'),array['example.com'],'Las exclusiones se aplican a la clasificación');
select throws_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select value->'settings' from config))$q$,'P0001','SETTINGS_CHANGED','Una copia antigua no sobrescribe ajustes nuevos');
update config set value=public.get_automation_configuration('00000000-0000-4000-8000-000000000531');
select throws_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select jsonb_set(value->'settings','{execution,pollIntervalSeconds}','0') from config))$q$,'23514','INVALID_INPUT','No se permite un intervalo fuera de rango');
select throws_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select jsonb_set(jsonb_set(value->'settings','{policy,blockedTopics}','["descuentos"]'),'{excludedDomains}','["https://invalid"]') from config))$q$,'23514',null::text,'Un dato inválido revierte el lote completo');
select is(public.get_automation_configuration('00000000-0000-4000-8000-000000000531'),(select value from config),'No se modifican ni las políticas ni las exclusiones tras un error');
select throws_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select (value->'settings')||'{"userId":"another"}' from config))$q$,'23514','INVALID_INPUT','No se aceptan campos adicionales');
select throws_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select jsonb_set(value->'settings','{policy,sourceRequirements}','[{"kind":"PRICE","sourceIds":["ffffffff-ffff-4fff-8fff-ffffffffffff"]}]') from config))$q$,'23514','INVALID_RESPONSE_POLICY_SOURCE','No se exige evidencia de fuentes ajenas');
update public.gmail_accounts set manual_sync_requested_at=clock_timestamp(),manual_processing_until=clock_timestamp()+interval '5 minutes' where user_id='00000000-0000-4000-8000-000000000531';
select lives_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select value->'settings' from config))$q$,'El interruptor puede pausar el procesamiento');
select is((select manual_processing_until from public.gmail_accounts where user_id='00000000-0000-4000-8000-000000000531'),null::timestamptz,'La pausa retira las revisiones manuales pendientes');
select ok(not has_function_privilege('authenticated','public.set_automation_configuration(uuid,text,jsonb)','EXECUTE'),'El navegador no puede ejecutar escrituras privilegiadas');
select ok(not has_function_privilege('anon','public.get_automation_configuration(uuid)','EXECUTE'),'No se publica la configuración');
update public.users set status='DISABLED' where id='00000000-0000-4000-8000-000000000531';
select throws_ok($q$select public.set_automation_configuration('00000000-0000-4000-8000-000000000531',(select value->>'revision' from config),(select value->'settings' from config))$q$,'P0001','FORBIDDEN','Una identidad suspendida no guarda configuración');
select * from finish();
rollback;
